const CatalogObjectSchema: z.ZodType<CatalogObjectType> = z
  .lazy(() =>
    z
      .object({
        absent_at_location_ids: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'A list of locations where the object is not present, even if `present_at_all_locations` is `true`.\nThis can include locations that are deactivated.',
          }),
        catalog_v1_ids: z
          .array(CatalogV1IdSchema)
          .exactOptional()
          .openapi({
            description:
              "The Connect v1 IDs for this object at each location where it is present, where they\ndiffer from the object's Connect V2 ID. The field will only be present for objects that\nhave been created or modified by legacy APIs.",
          }),
        category_data: CatalogCategorySchema.exactOptional(),
        custom_attribute_definition_data: CatalogCustomAttributeDefinitionSchema.exactOptional(),
        custom_attribute_values: z
          .record(z.string(), CatalogCustomAttributeValueSchema)
          .exactOptional()
          .openapi({
            description:
              'A map (key-value pairs) of application-defined custom attribute values. The value of a key-value pair\nis a [CatalogCustomAttributeValue](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogCustomAttributeValue) object. The key is the `key` attribute\nvalue defined in the associated [CatalogCustomAttributeDefinition](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogCustomAttributeDefinition)\nobject defined by the application making the request.\n\nIf the `CatalogCustomAttributeDefinition` object is\ndefined by another application, the `CatalogCustomAttributeDefinition`\'s key attribute value is prefixed by\nthe defining application ID. For example, if the `CatalogCustomAttributeDefinition` has a `key` attribute of\n`"cocoa_brand"` and the defining application ID is `"abcd1234"`, the key in the map is `"abcd1234:cocoa_brand"`\nif the application making the request is different from the application defining the custom attribute definition.\nOtherwise, the key used in the map is simply `"cocoa_brand"`.\n\nApplication-defined custom attributes that are set at a global (location-independent) level.\nCustom attribute values are intended to store additional information about a catalog object\nor associations with an entity in another system. Do not use custom attributes\nto store any sensitive information (personally identifiable information, card details, etc.).',
            'x-is-beta': true,
            'x-release-status': 'BETA',
          }),
        discount_data: CatalogDiscountSchema.exactOptional(),
        id: z
          .string()
          .min(1)
          .openapi({
            description:
              'An identifier to reference this object in the catalog. When a new `CatalogObject`\nis inserted, the client should set the id to a temporary identifier starting with\na "`#`" character. Other objects being inserted or updated within the same request\nmay use this identifier to refer to the new object.\n\nWhen the server receives the new object, it will supply a unique identifier that\nreplaces the temporary identifier for all future references.',
          }),
        image_data: CatalogImageSchema.exactOptional(),
        image_id: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Identifies the `CatalogImage` attached to this `CatalogObject`.',
          }),
        is_deleted: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'If `true`, the object has been deleted from the database. Must be `false` for new objects\nbeing inserted. When deleted, the `updated_at` field will equal the deletion time.',
          }),
        item_data: CatalogItemSchema.exactOptional(),
        item_option_data: CatalogItemOptionSchema.exactOptional(),
        item_option_value_data: CatalogItemOptionValueSchema.exactOptional(),
        item_variation_data: CatalogItemVariationSchema.exactOptional(),
        measurement_unit_data: CatalogMeasurementUnitSchema.exactOptional(),
        modifier_data: CatalogModifierSchema.exactOptional(),
        modifier_list_data: CatalogModifierListSchema.exactOptional(),
        present_at_all_locations: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'If `true`, this object is present at all locations (including future locations), except where specified in\nthe `absent_at_location_ids` field. If `false`, this object is not present at any locations (including future locations),\nexcept where specified in the `present_at_location_ids` field. If not specified, defaults to `true`.',
          }),
        present_at_location_ids: z
          .array(z.string())
          .exactOptional()
          .openapi({
            description:
              'A list of locations where the object is present, even if `present_at_all_locations` is `false`.\nThis can include locations that are deactivated.',
          }),
        pricing_rule_data: CatalogPricingRuleSchema.exactOptional(),
        product_set_data: CatalogProductSetSchema.exactOptional(),
        quick_amounts_settings_data: CatalogQuickAmountsSettingsSchema.exactOptional(),
        subscription_plan_data: CatalogSubscriptionPlanSchema.exactOptional(),
        tax_data: CatalogTaxSchema.exactOptional(),
        time_period_data: CatalogTimePeriodSchema.exactOptional(),
        type: z
          .string()
          .openapi({
            description:
              'The type of this object. Each object type has expected\nproperties expressed in a structured format within its corresponding `*_data` field below.',
          }),
        updated_at: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Last modification [timestamp](https://developer.squareup.com/docs/build-basics/working-with-dates) in RFC 3339 format, e.g., `"2016-08-15T23:59:33.123Z"`\nwould indicate the UTC time (denoted by `Z`) of August 15, 2016 at 23:59:33 and 123 milliseconds.',
            'x-read-only': true,
          }),
        version: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .exactOptional()
          .openapi({
            type: 'integer',
            format: 'int64',
            description:
              'The version of the object. When updating an object, the version supplied\nmust match the version in the database, otherwise the write will be rejected as conflicting.',
          }),
      })
      .openapi({
        description:
          'The wrapper object for the Catalog entries of a given object type.\n\nThe type of a particular `CatalogObject` is determined by the value of the\n`type` attribute and only the corresponding data attribute can be set on the `CatalogObject` instance.\nFor example, the following list shows some instances of `CatalogObject` of a given `type` and\ntheir corresponding data attribute that can be set:\n- For a `CatalogObject` of the `ITEM` type, set the `item_data` attribute to yield the `CatalogItem` object.\n- For a `CatalogObject` of the `ITEM_VARIATION` type, set the `item_variation_data` attribute to yield the `CatalogItemVariation` object.\n- For a `CatalogObject` of the `MODIFIER` type, set the `modifier_data` attribute to yield the `CatalogModifier` object.\n- For a `CatalogObject` of the `MODIFIER_LIST` type, set the `modifier_list_data` attribute to yield the `CatalogModifierList` object.\n- For a `CatalogObject` of the `CATEGORY` type, set the `category_data` attribute to yield the `CatalogCategory` object.\n- For a `CatalogObject` of the `DISCOUNT` type, set the `discount_data` attribute to yield the `CatalogDiscount` object.\n- For a `CatalogObject` of the `TAX` type, set the `tax_data` attribute to yield the `CatalogTax` object.\n- For a `CatalogObject` of the `IMAGE` type, set the `image_data` attribute to yield the `CatalogImageData`  object.\n- For a `CatalogObject` of the `QUICK_AMOUNTS_SETTINGS` type, set the `quick_amounts_settings_data` attribute to yield the `CatalogQuickAmountsSettings` object.\n- For a `CatalogObject` of the `PRICING_RULE` type, set the `pricing_rule_data` attribute to yield the `CatalogPricingRule` object.\n- For a `CatalogObject` of the `TIME_PERIOD` type, set the `time_period_data` attribute to yield the `CatalogTimePeriod` object.\n- For a `CatalogObject` of the `PRODUCT_SET` type, set the `product_set_data` attribute to yield the `CatalogProductSet`  object.\n- For a `CatalogObject` of the `SUBSCRIPTION_PLAN` type, set the `subscription_plan_data` attribute to yield the `CatalogSubscriptionPlan` object.\n\n\nFor a more detailed discussion of the Catalog data model, please see the\n[Design a Catalog](https://developer.squareup.com/docs/catalog-api/design-a-catalog) guide.',
        example: {
          catalog_object: {
            absent_at_location_ids: ['{{ LOCATIONID-1 }}', '{{ LOCATIONID-N }}'],
            category_data: '{{ CatalogCategory object only if type=CATEGORY }}',
            connect_v1_ids: {
              catalog_v1_id: '{{ itemID from Catalog v1 }}',
              location_id: '{{ location where v1 ID is used }}',
            },
            discount_data: '{{ CatalogDiscount object only if type=DISCOUNT }}',
            id: '{{ set by Catalog during object creation }}',
            is_deleted: '{{ [true | false] }}',
            item_data: '{{ CatalogItem object only if type=ITEM }}',
            item_variation_data: '{{ CatalogItemVariation object only if type=ITEM_VARIATION }}',
            modifier_data: '{{ CatalogModifier object only if type=MODIFIER }}',
            modifier_list_data: '{{ CatalogModifierList object only if type=MODIFIER_LIST }}',
            present_at_all_locations: '{{ [true | false] }}',
            present_at_location_ids: ['{{ LOCATIONID-1 }}', '{{ LOCATIONID-N }}'],
            tax_data: '{{ CatalogTax object only if type=TAX }}',
            type: '{{ [ITEM | ITEM_VARIATION | MODIFIER | MODIFIER_LIST | CATEGORY | DISCOUNT | TAX] }}',
            updated_at: '{{ date & time of most recent update }}',
            version: '{{ version of the CatalogObject }}',
          },
        },
        required: ['type', 'id'],
        'x-example_type': 'Schema',
        'x-release-status': 'PUBLIC',
      }),
  )
  .openapi('CatalogObject')

