const CatalogStockConversionSchema = z
  .object({
    nonstockable_quantity: z
      .string()
      .min(1)
      .max(16)
      .openapi({
        description:
          'The converted equivalent quantity of the non-stockable [CatalogItemVariation](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItemVariation) \nin its measurement unit. The `stockable_quantity` value and this `nonstockable_quantity` value together\ndefine the conversion ratio between stockable item variation and the non-stockable item variation.\nIt accepts a decimal number in a string format that can take up to 10 digits before the decimal point\nand up to 5 digits after the decimal point.',
      }),
    stockable_item_variation_id: z
      .string()
      .min(1)
      .openapi({
        description:
          'References to the stockable [CatalogItemVariation](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItemVariation)\nfor this stock conversion. Selling, receiving or recounting the non-stockable `CatalogItemVariation` \ndefined with a stock conversion results in adjustments of this stockable `CatalogItemVariation`.\nThis immutable field must reference a stockable `CatalogItemVariation`\nthat shares the parent [CatalogItem](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItem) of the converted `CatalogItemVariation.`',
      }),
    stockable_quantity: z
      .string()
      .min(1)
      .max(16)
      .openapi({
        description:
          'The quantity of the stockable item variation (as identified by `stockable_item_variation_id`) \nequivalent to the non-stockable item variation quantity (as specified in `nonstockable_quantity`) \nas defined by this stock conversion.  It accepts a decimal number in a string format that can take\nup to 10 digits before the decimal point and up to 5 digits after the decimal point.',
      }),
  })
  .openapi({
    description:
      'Represents the rule of conversion between a stockable [CatalogItemVariation](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItemVariation)\nand a non-stockable sell-by or receive-by `CatalogItemVariation` that\nshare the same underlying stock.',
    required: ['stockable_item_variation_id', 'stockable_quantity', 'nonstockable_quantity'],
    'x-is-beta': true,
    'x-release-status': 'BETA',
  })
  .openapi('CatalogStockConversion')

