export const getV2CatalogObjectObjectIdRoute = createRoute({
  method: 'get',
  path: '/v2/catalog/object/{object_id}',
  tags: ['Catalog'],
  summary: 'RetrieveCatalogObject',
  description:
    'Returns a single [CatalogItem](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItem) as a\n[CatalogObject](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogObject) based on the provided ID. The returned\nobject includes all of the relevant [CatalogItem](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItem)\ninformation including: [CatalogItemVariation](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogItemVariation)\nchildren, references to its\n[CatalogModifierList](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogModifierList) objects, and the ids of\nany [CatalogTax](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogTax) objects that apply to it.',
  operationId: 'RetrieveCatalogObject',
  request: {
    params: z.object({
      object_id: z
        .string()
        .openapi({
          param: {
            description: 'The object ID of any type of catalog objects to be retrieved.',
            in: 'path',
            name: 'object_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      include_related_objects: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'If `true`, the response will include additional objects that are related to the\nrequested object, as follows:\n\nIf the `object` field of the response contains a `CatalogItem`, its associated\n`CatalogCategory`, `CatalogTax`, `CatalogImage` and `CatalogModifierList` objects will\nbe returned in the `related_objects` field of the response. If the `object` field of\nthe response contains a `CatalogItemVariation`, its parent `CatalogItem` will be returned\nin the `related_objects` field of the response.\n\nDefault value: `false`',
            in: 'query',
            name: 'include_related_objects',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      catalog_version: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'Requests objects as of a specific version of the catalog. This allows you to retrieve historical\nversions of objects. The value to retrieve a specific version of an object can be found\nin the version field of [CatalogObject](https://developer.squareup.com/reference/square_2021-08-18/objects/CatalogObject)s.',
            in: 'query',
            name: 'catalog_version',
            required: false,
            schema: { format: 'int64', type: 'integer' },
            'x-is-beta': true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: RetrieveCatalogObjectResponseSchema } },
    },
  },
  security: [{ oauth2: ['ITEMS_READ'] }],
})

