export const deleteV2CustomersCustomerIdRoute = createRoute({
  method: 'delete',
  path: '/v2/customers/{customer_id}',
  tags: ['Customers'],
  summary: 'DeleteCustomer',
  description:
    'Deletes a customer profile from a business. This operation also unlinks any associated cards on file. \n\nAs a best practice, you should include the `version` field in the request to enable [optimistic concurrency](https://developer.squareup.com/docs/working-with-apis/optimistic-concurrency) control. The value must be set to the current version of the customer profile. \n\nTo delete a customer profile that was created by merging existing profiles, you must use the ID of the newly created profile.',
  operationId: 'DeleteCustomer',
  request: {
    params: z.object({
      customer_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the customer to delete.',
            in: 'path',
            name: 'customer_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      version: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description:
              'The current version of the customer profile.\n\nAs a best practice, you should include this parameter to enable [optimistic concurrency](https://developer.squareup.com/docs/working-with-apis/optimistic-concurrency) control.  For more information, see [Delete a customer profile](https://developer.squareup.com/docs/customers-api/use-the-api/keep-records#delete-customer-profile).',
            in: 'query',
            name: 'version',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: DeleteCustomerResponseSchema } },
    },
  },
  security: [{ oauth2: ['CUSTOMERS_WRITE'] }],
})

