export const getV2MerchantsRoute = createRoute({
  method: 'get',
  path: '/v2/merchants',
  tags: ['Merchants'],
  summary: 'ListMerchants',
  description:
    "Returns `Merchant` information for a given access token.\n\nIf you don't know a `Merchant` ID, you can use this endpoint to retrieve the merchant ID for an access token.\nYou can specify your personal access token to get your own merchant information or specify an OAuth token\nto get the information for the  merchant that granted you access.\n\nIf you know the merchant ID, you can also use the [RetrieveMerchant](https://developer.squareup.com/reference/square_2021-08-18/merchants-api/retrieve-merchant)\nendpoint to get the merchant information.",
  operationId: 'ListMerchants',
  request: {
    query: z.object({
      cursor: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The cursor generated by the previous response.',
            in: 'query',
            name: 'cursor',
            required: false,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ListMerchantsResponseSchema } },
    },
  },
  security: [{ oauth2: ['MERCHANT_PROFILE_READ'] }],
})

