export const getV2PaymentsRoute = createRoute({
  method: 'get',
  path: '/v2/payments',
  tags: ['Payments'],
  summary: 'ListPayments',
  description:
    'Retrieves a list of payments taken by the account making the request.\n\nResults are eventually consistent, and new payments or changes to payments might take several\nseconds to appear.\n\nThe maximum results per page is 100.',
  request: {
    query: z.object({
      begin_time: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The timestamp for the beginning of the reporting period, in RFC 3339 format.\nInclusive. Default: The current time minus one year.',
            in: 'query',
            name: 'begin_time',
            required: false,
            schema: { type: 'string' },
          },
        }),
      end_time: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The timestamp for the end of the reporting period, in RFC 3339 format.\n\nDefault: The current time.',
            in: 'query',
            name: 'end_time',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort_order: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The order in which results are listed:\n- `ASC` - Oldest to newest.\n- `DESC` - Newest to oldest (default).',
            in: 'query',
            name: 'sort_order',
            required: false,
            schema: { type: 'string' },
          },
        }),
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A pagination cursor returned by a previous call to this endpoint.\nProvide this cursor to retrieve the next set of results for the original query.\n\nFor more information, see [Pagination](https://developer.squareup.com/docs/basics/api101/pagination).',
            in: 'query',
            name: 'cursor',
            required: false,
            schema: { type: 'string' },
          },
        }),
      location_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Limit results to the location supplied. By default, results are returned\nfor the default (main) location associated with the seller.',
            in: 'query',
            name: 'location_id',
            required: false,
            schema: { type: 'string' },
          },
        }),
      total: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            description: 'The exact amount in the `total_money` for a payment.',
            in: 'query',
            name: 'total',
            required: false,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      last_4: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The last four digits of a payment card.',
            in: 'query',
            name: 'last_4',
            required: false,
            schema: { type: 'string' },
          },
        }),
      card_brand: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The brand of the payment card (for example, VISA).',
            in: 'query',
            name: 'card_brand',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The maximum number of results to be returned in a single page.\nIt is possible to receive fewer results than the specified limit on a given page.\n\nThe default value of 100 is also the maximum allowed value. If the provided value is \ngreater than 100, it is ignored and the default value is used instead.\n\nDefault: `100`',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ListPaymentsResponseSchema } },
    },
  },
  security: [{ oauth2: ['PAYMENTS_READ'] }],
})

