export const getV2SubscriptionsSubscriptionIdEventsRoute = createRoute({
  method: 'get',
  path: '/v2/subscriptions/{subscription_id}/events',
  tags: ['Subscriptions'],
  summary: 'ListSubscriptionEvents',
  description:
    'Lists all events for a specific subscription.\nIn the current implementation, only `START_SUBSCRIPTION` and `STOP_SUBSCRIPTION` (when the subscription was canceled) events are returned.',
  operationId: 'ListSubscriptionEvents',
  request: {
    params: z.object({
      subscription_id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the subscription to retrieve the events for.',
            in: 'path',
            name: 'subscription_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'A pagination cursor returned by a previous call to this endpoint.\nProvide this to retrieve the next set of results for the original query.\n\nFor more information, see [Pagination](https://developer.squareup.com/docs/working-with-apis/pagination).',
            in: 'query',
            name: 'cursor',
            required: false,
            schema: { type: 'string' },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The upper limit on the number of subscription events to return\nin the response.\n\nDefault: `200`',
            in: 'query',
            name: 'limit',
            required: false,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'application/json': { schema: ListSubscriptionEventsResponseSchema } },
    },
  },
  security: [{ oauth2: ['SUBSCRIPTIONS_READ'] }],
})

